import type { Localized, PluginContent, PluginCopy, UpstreamProject } from "./types";

const upstream = (name: string, version: string, projectUrl: string, license: string, en: string, zh: string, noticeUrl?: string): UpstreamProject => ({
  name, version, projectUrl, license, noticeUrl, usage: { en, "zh-CN": zh },
});

const plugin = (
  pluginId: string,
  title: Localized<string>,
  description: Localized<string>,
  summary: Localized<string>,
  architecture: Localized<readonly string[]>,
  limitations: Localized<readonly string[]>,
  upstreamProjects: readonly UpstreamProject[] = [],
): PluginContent => ({
  pluginId, status: "published", upstreamProjects,
  copy: Object.fromEntries((["en", "zh-CN"] as const).map((locale) => [locale, {
    title: title[locale], description: description[locale], summary: summary[locale],
    architecture: architecture[locale], limitations: limitations[locale],
  }])) as Localized<PluginCopy>,
});

